<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';use Kulturhus\Verein\InvoiceRecognition;
$dir=sys_get_temp_dir().'/ocr-lock-test-'.bin2hex(random_bytes(8));mkdir($dir,0700);$config=$dir.'/runtime.json';file_put_contents($config,json_encode(['python'=>PHP_BINARY]));$old=getenv('VEREIN_OCR_RUNTIME');putenv('VEREIN_OCR_RUNTIME='.$config);$lock=fopen($dir.'/invoice-recognition.lock','c');flock($lock,LOCK_EX|LOCK_NB);
try{try{InvoiceRecognition::extract('%PDF-1.4','application/pdf');throw new RuntimeException('busy runtime admitted another worker');}catch(DomainException $e){if(!str_contains($e->getMessage(),'gerade eine Rechnung'))throw $e;echo "PASS shared runtime lock rejects another worker without waiting\n";}flock($lock,LOCK_UN);fclose($lock);$lock=null;try{InvoiceRecognition::extract('%PDF-1.4','application/pdf');}catch(DomainException){}$probe=fopen($dir.'/invoice-recognition.lock','c');if(!flock($probe,LOCK_EX|LOCK_NB))throw new RuntimeException('lock leaked after failure');flock($probe,LOCK_UN);fclose($probe);echo "PASS failure releases shared runtime lock\n";}finally{if(is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}putenv($old===false?'VEREIN_OCR_RUNTIME':'VEREIN_OCR_RUNTIME='.$old);unlink($config);unlink($dir.'/invoice-recognition.lock');rmdir($dir);}
